// Title: Waiting for Pong
// Author: Claude, ItsWesSmithYo
// Project: OneManShYo

void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    // Normalize coordinates
    vec2 uv = fragCoord / iResolution.xy;
    uv = uv * 2.0 - 1.0;  // Map to [-1, 1]
    uv.x *= iResolution.x / iResolution.y;  // Adjust for aspect ratio

    // Time variable
    float t = iTime;

    // Paddle properties
    float paddleWidth = 0.4;
    float paddleHeight = 0.05;
    vec2 paddlePos = vec2(sin(t * 0.5) * 0.8, -0.9);  // Paddle moves left and right

    // Ball position (STATIC)
    vec2 ballPos = vec2(0.0, 0.5);  // Ball stays in the middle

    // Render paddle
    float paddle = step(abs(uv.x - paddlePos.x), paddleWidth) *
                   step(abs(uv.y - paddlePos.y), paddleHeight);

    // Render ball (static)
    float ball = smoothstep(0.05, 0.03, length(uv - ballPos));

    // Background
    vec3 color = vec3(0.0);  // Black background

    // Combine paddle and ball colors
    color += vec3(1.0, 0.0, 0.0) * paddle;  // Red paddle
    color += vec3(1.0, 1.0, 1.0) * ball;    // White ball

    // Output final color
    fragColor = vec4(color, 1.0);
}
